#include <cstdio>
#include <cstdlib>
using namespace std;

typedef long long ll;
const ll INF = 1000000000000000000LL;
ll global_ans = 0;
vector<ll> dp_table;

ll compute_solution(ll value) {
    if (value == 0) return 0;
    if (value < (ll)dp_table.size() && dp_table[value] != 0) return dp_table[value];

    ll min_diff = INF;
    ll current_val = 1;
    ll count_ops = 0;

    while (abs(current_val - value) <= min_diff) {
        min_diff = abs(current_val - value);
        current_val = current_val * 10 + 1;
        count_ops++;
    }

    current_val /= 10;

    if (current_val > value && current_val / 10) {
        ll path1 = count_ops + compute_solution(abs(current_val - value));
        ll path2 = (count_ops - 1) + compute_solution(abs(current_val / 10 - value));
        if (value < (ll)dp_table.size()) return dp_table[value] = min(path1, path2);
        return min(path1, path2);
    }

    ll final_result = count_ops + compute_solution(abs(current_val - value));
    if (value < (ll)dp_table.size()) return dp_table[value] = final_result;
    return final_result;
}

int main() {
#ifdef NEKROLM
    freopen("input.txt", "r", stdin);
    freopen("output.txt", "w", stdout);
#endif
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll input_value;
    cin >> input_value;
    dp_table.assign(100000000, 0);
    cout << compute_solution(input_value);

    return 0;
}
